#include <iostream>
using namespace std;

int main() {
    const int SIZE = 5;
    int marks[SIZE] = {70, 85, 62, 90, 78};
    int sum = 0;
    for (int i = 0; i < SIZE; i++) {
        sum += marks[i];
    }
    cout << "Sum: " << sum << endl;
    cout << "Average: " << (double)sum / SIZE << endl;
    return 0;
}

